int main(int argc,char**argv){int runs=argc>2?atoi(argv[2]):3;int ref=argc>3?atoi(argv[3]):0;int m=argc>5?atoi(argv[5]):4;int s=argc>6?atoi(argv[6]):2;if(m+s>12)return 4;int odd=argc>4?atoi(argv[4]):0;mt19937_64 R(2026110501);int g[]={7,1,4,4,2,7,3,3,4,7,2,1};int G[12][24]={},gray[8];unsigned char map[24][8];ifstream f(argv[1],ios::binary);f.read((char*)map,sizeof(map));if(!f)return 2;for(int i=0;i<12;i++){for(int j=0;j<12;j++)G[i][i+j]=g[j];G[i][23]=3;}int offset[24]={};for(int q=0;q<8;q++){gray[q]=0;for(int x=0;x<2;x++)for(int y=0;y<2;y++)gray[q]|=(((q>>2&1)^((q&1)*x)^((q>>1&1)*y))<<(2*x+y));}int best=96;
for(int run=0;run<runs;run++){int ca[12],cb[12],a[24]={},b[24]={};for(int i=0;i<12;i++){if(i<m){int va[6],vb[6],na=0,nb=0;for(int z=0;z<8;z++){if(__builtin_popcount((unsigned)map[i][z])==2)va[na++]=z;if(__builtin_popcount((unsigned)gray[z])==2)vb[nb++]=z;}if(na!=6||nb!=6)return 3;ca[i]=(7*(va[R()%na]-a[i]))&7;cb[i]=(7*(vb[R()%nb]-b[i]))&7;}else{ca[i]=i<m+s?2*(R()&3):(R()&7);cb[i]=R()&7;}for(int j=0;j<24;j++){a[j]=(a[j]+ca[i]*G[i][j])&7;b[j]=(b[j]+cb[i]*G[i][j])&7;}}for(int j=0;j<24;j++)b[j]=(b[j]+offset[j])&7;auto dist=[&](){int s=0;for(int j=0;j<24;j++){s+=__builtin_popcount((unsigned)(map[j][a[j]]^gray[b[j]]^odd));if(j<m){s+=32*(__builtin_popcount((unsigned)map[j][a[j]])!=2);s+=32*(__builtin_popcount((unsigned)gray[b[j]])!=2);}}return s;};int cur=dist();for(int it=0;it<300000;it++){int side=R()&1,i=m+R()%(12-m),value=(side&&i<m+s)?2*(R()&3):(R()&7),*c=side?ca:cb,*v=side?a:b;int delta=value-c[i];if(!delta)continue;int nd=0;for(int j=0;j<24;j++){int aa=side?((a[j]+delta*G[i][j])&7):a[j],bb=side?b[j]:((b[j]+delta*G[i][j])&7);nd+=__builtin_popcount((unsigned)(map[j][aa]^gray[bb]^odd));if(j<m){nd+=32*(__builtin_popcount((unsigned)map[j][aa])!=2);nd+=32*(__builtin_popcount((unsigned)gray[bb])!=2);}}double T=.3+3.0*(1.0-double(it%30000)/30000);if(nd<=cur||double(R()>>11)*(1.0/9007199254740992.0)<exp((cur-nd)/T)){for(int j=0;j<24;j++)v[j]=(v[j]+delta*G[i][j])&7;c[i]=value;cur=nd;}best=min(best,cur);if(cur<24){printf("WITNESS A ");for(int x:ca)printf("%d",x);printf(" B ");for(int x:cb)printf("%d",x);printf(" distance %d\n",cur);return 0;}}}printf("UNRESOLVED best %d\n",best);}
